/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var dkmeansInitPlusPlus = require( './../lib/dkmeans_init_plus_plus.js' );


// FIXTURES //

var ROW_MAJOR_DATA = require( './fixtures/row_major.json' );
var COLUMN_MAJOR_DATA = require( './fixtures/column_major.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dkmeansInitPlusPlus, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 11', function test( t ) {
	t.strictEqual( dkmeansInitPlusPlus.length, 11, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a valid order', function test( t ) {
	var values;
	var data;
	var i;

	data = ROW_MAJOR_DATA;

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dkmeansInitPlusPlus( value, data.k, data.M, data.N, new Float64Array( data.out ), data.LDO, new Float64Array( data.X ), data.LDX, data.metric, data.trials, data.seed );
		};
	}
});

tape( 'the function throws an error if provided a sixth argument which is not a valid `LDO` value (row-major)', function test( t ) {
	var values;
	var data;
	var i;

	data = ROW_MAJOR_DATA;

	values = [
		0,
		1
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dkmeansInitPlusPlus( data.order, data.k, data.M, data.N, new Float64Array( data.out ), value, new Float64Array( data.X ), data.LDX, data.metric, data.trials, data.seed );
		};
	}
});

