tape( 'the function throws an error when trials is less than or equal to zero', function test( t ) {
	var data;

	data = ROW_MAJOR_DATA;
	t.throws( badValue( 0 ), RangeError, 'throws an error when provided ' + 0 );
	t.end();

	function badValue( value ) {
		return function badValue() {
			dkmeansInitPlusPlus( data.order, data.k, data.M, data.N, new Float64Array( data.out ), value, new Float64Array( data.X ), data.LDX, data.metric, data.trials, data.seed );
		};
	}
});

tape( 'the function returns a NaN array when M is less than or equal to zero', function test( t ) {
	var data;
	var out;

	data = ROW_MAJOR_DATA;
	out = dkmeansInitPlusPlus( data.order, data.k, 0, data.N, new Float64Array( data.out ), data.LDO, new Float64Array( data.X ), data.LDX, data.metric, data.trials, data.seed );

	t.strictEqual( isAlmostSameValue( out, NaN, 0), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns a NaN array when N is less than or equal to zero', function test( t ) {
	var data;
	var out;

	data = ROW_MAJOR_DATA;
	out = dkmeansInitPlusPlus( data.order, data.k, data.M, 0, new Float64Array( data.out ), data.LDO, new Float64Array( data.X ), data.LDX, data.metric, data.trials, data.seed );

	t.strictEqual( isAlmostSameValue( out, NaN, 0), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns the centroids (row-major)', function test( t ) {
	var expected;
	var data;
	var out;
	var i;

	data = ROW_MAJOR_DATA;
	out = dkmeansInitPlusPlus( data.order, data.k, data.M, data.N, new Float64Array( data.out ), data.LDO, new Float64Array( data.X ), data.LDX, data.metric, data.trials, data.seed );

	expected = new Float64Array( data.expected );
	for ( i = 0; i < expected.length; i++ ) {
		t.strictEqual( isAlmostSameValue( out[ i ], expected[ i ], 0 ), true, 'returns expected value' );
	}
	t.end();
});

